#include <vector>
#include <omp.h>

void relu(std::vector<double> &x) {
    const std::size_t n = x.size();
    #pragma omp parallel for schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        const double v = x[i];
        x[i] = (v > 0.0) ? v : 0.0;
    }
}
